using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;

namespace Sace.Api.Services;

public interface IDocumentLineItemMatcher {
  IReadOnlyList<DocumentLineItemMatch> Match(IReadOnlyList<DocumentLineItem> left,IReadOnlyList<DocumentLineItem> right);
}

public sealed class DocumentLineItemMatcher : IDocumentLineItemMatcher {
  public IReadOnlyList<DocumentLineItemMatch> Match(IReadOnlyList<DocumentLineItem> left,IReadOnlyList<DocumentLineItem> right){
    var result=new List<DocumentLineItemMatch>();var used=new HashSet<Guid>();
    foreach(var item in left.OrderBy(x=>x.Sequence)){
      var (method,key,candidates)=Candidates(item,right.Where(x=>!used.Contains(x.Id)).ToList());
      if(candidates.Count==1){var target=candidates[0];used.Add(target.Id);result.Add(M(item,target,method,key,LineItemMatchStatus.MATCHED,$"Partidas vinculadas mediante {method}: {key}."));}
      else if(candidates.Count>1)result.Add(M(item,null,method,key,LineItemMatchStatus.AMBIGUOUS,"Se encontraron múltiples partidas candidatas."));
      else result.Add(M(item,null,LineItemMatchMethod.NONE,null,LineItemMatchStatus.UNMATCHED_LEFT,"La partida izquierda no tiene candidata determinista."));
    }
    foreach(var item in right.Where(x=>!used.Contains(x.Id)).OrderBy(x=>x.Sequence))result.Add(M(null,item,LineItemMatchMethod.NONE,null,LineItemMatchStatus.UNMATCHED_RIGHT,"La partida derecha no tiene candidata determinista."));
    return result;
  }
  private static (LineItemMatchMethod method,string? key,List<DocumentLineItem> candidates) Candidates(DocumentLineItem item,List<DocumentLineItem> available){
    var part=Key(item.PartNumber??item.Sku);if(part is not null){var rows=available.Where(x=>Key(x.PartNumber??x.Sku)==part).ToList();return(LineItemMatchMethod.PART_NUMBER,part,rows);}
    var number=Key(item.ItemNumber);if(number is not null){var rows=available.Where(x=>Key(x.ItemNumber)==number).ToList();if(rows.Count>0)return(LineItemMatchMethod.ITEM_REFERENCE,number,rows);}
    var strong=Strong(item);if(strong is not null)return(LineItemMatchMethod.DESCRIPTION_QUANTITY_UNIT,strong,available.Where(x=>Strong(x)==strong).ToList());
    return(LineItemMatchMethod.NONE,null,[]);
  }
  private static string? Strong(DocumentLineItem item){var description=Text(item.Description);var unit=Unit(item.Unit);return description is null||!item.Quantity.HasValue||unit is null?null:$"{description}|{item.Quantity.Value.ToString(CultureInfo.InvariantCulture)}|{unit}";}
  private static string? Key(string? value)=>string.IsNullOrWhiteSpace(value)?null:Regex.Replace(value.Trim().ToUpperInvariant(),@"[^A-Z0-9]","");
  private static string? Text(string? value)=>string.IsNullOrWhiteSpace(value)?null:Regex.Replace(value.Trim().ToUpperInvariant(),@"[\p{P}\s]+"," ").Trim();
  private static string? Unit(string? value)=>value?.Trim().ToUpperInvariant() switch{"PIEZA" or "PIEZAS" or "PZ" or "PZS" or "PCS"=>"PZA","KGS"=>"KG","LBS"=>"LB",var v=>v};
  private static DocumentLineItemMatch M(DocumentLineItem? left,DocumentLineItem? right,LineItemMatchMethod method,string? key,LineItemMatchStatus status,string explanation)=>new(){LeftLineItemId=left?.Id,RightLineItemId=right?.Id,MatchMethod=method,MatchKey=key,Status=status,Explanation=explanation,LeftItemSnapshot=left is null?null:JsonSerializer.Serialize(Snapshot(left)),RightItemSnapshot=right is null?null:JsonSerializer.Serialize(Snapshot(right))};
  private static object Snapshot(DocumentLineItem x)=>new{x.Sequence,x.ItemNumber,x.PartNumber,x.Sku,x.Description,x.Quantity,x.Unit,x.UnitValue,x.TotalValue,x.Currency,x.TariffFraction,x.Nico,x.GrossWeight,x.NetWeight,x.CountryOfOrigin,x.RawLocator,x.ExtractionMethod,x.Confidence};
}

public interface IDocumentReconciliationService {
  Task<IReadOnlyList<DocumentReconciliationResult>> RunAsync(Guid operationId,Guid userId,CancellationToken ct=default);
}

public sealed class DocumentReconciliationService(SaceDbContext db,IDocumentLineItemMatcher matcher) : IDocumentReconciliationService {
  private sealed record Pair(OperationDocument? Left,OperationDocument? Right,bool Ambiguous,string Explanation);
  private sealed record ValueSnapshot(Guid? FieldId,string? Raw,string? Normalized,ExtractionMethod? Method);
  private static readonly Dictionary<string,string[]> Aliases=new(StringComparer.OrdinalIgnoreCase){["COMMERCIAL_INVOICE"]=["COMMERCIAL_INVOICE","INVOICE"],["COVE_ACK"]=["COVE_ACK"],["PACKING_LIST"]=["PACKING_LIST"],["TRANSPORT_DOCUMENT"]=["TRANSPORT_DOCUMENT"],["PEDIMENTO"]=["PEDIMENTO"]};

  public async Task<IReadOnlyList<DocumentReconciliationResult>> RunAsync(Guid operationId,Guid userId,CancellationToken ct=default){
    var operation=await db.TradeOperations.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==operationId,ct)??throw new KeyNotFoundException("Operación no localizada.");var validUser=await ValidUser(userId,ct);
    db.SystemAuditLogs.Add(new SystemAuditLog{UserId=validUser,Action="DOCUMENT_RECONCILIATION_STARTED",EntityType="TradeOperation",EntityId=operationId.ToString(),Details="Inició la reconciliación documental integral."});await db.SaveChangesAsync(ct);
    var documents=await db.OperationDocuments.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.DocumentType).Include(x=>x.References).Include(x=>x.Fields).Include(x=>x.LineItems).ToListAsync(ct);
    var profiles=await db.DocumentReconciliationProfiles.AsNoTracking().Where(x=>x.Status==ReconciliationProfileStatus.ACTIVE&&(x.EffectiveFrom==null||x.EffectiveFrom<=operation.OperationDate)&&(x.EffectiveTo==null||operation.OperationDate<=x.EffectiveTo)).Include(x=>x.Fields.Where(f=>f.IsActive)).ThenInclude(x=>x.CrossValidationRule).OrderBy(x=>x.Code).ToListAsync(ct);
    var crosses=await db.CrossValidationResults.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.SourceField).Include(x=>x.TargetField).OrderByDescending(x=>x.EvaluatedAt).ToListAsync(ct);var results=new List<DocumentReconciliationResult>();
    foreach(var profile in profiles){var left=OfType(documents,profile.LeftDocumentTypeCode);var right=OfType(documents,profile.RightDocumentTypeCode);if(left.Count==0&&right.Count==0)continue;foreach(var pair in PairDocuments(left,right)){var result=Build(operation,profile,pair,crosses);db.DocumentReconciliationResults.Add(result);results.Add(result);}}
    var manual=results.Count(x=>x.Outcome==ReconciliationOutcome.MANUAL_REVIEW);db.SystemAuditLogs.Add(new SystemAuditLog{UserId=validUser,Action="DOCUMENT_RECONCILIATION_COMPLETED",EntityType="TradeOperation",EntityId=operationId.ToString(),Details=$"{results.Count} reconciliaciones: {results.Count(x=>x.Outcome==ReconciliationOutcome.MATCH)} coincidencias, {results.Count(x=>x.Outcome==ReconciliationOutcome.WITH_DIFFERENCES)} con diferencias, {manual} en revisión manual."});if(manual>0)db.SystemAuditLogs.Add(new SystemAuditLog{UserId=validUser,Action="DOCUMENT_RECONCILIATION_MANUAL_REVIEW",EntityType="TradeOperation",EntityId=operationId.ToString(),Details=$"{manual} reconciliaciones requieren revisión humana."});await db.SaveChangesAsync(ct);return results;
  }

  private DocumentReconciliationResult Build(TradeOperation operation,DocumentReconciliationProfile profile,Pair pair,List<CrossValidationResult> crosses){
    var result=new DocumentReconciliationResult{TradeOperationId=operation.Id,ProfileId=profile.Id,ProfileCode=profile.Code,ProfileVersion=profile.Version,LeftDocumentId=pair.Left?.Id,RightDocumentId=pair.Right?.Id,EvaluatedAt=DateTime.UtcNow};
    foreach(var field in profile.Fields.Where(x=>x.LineItemScope==LineItemScope.HEADER).OrderBy(x=>x.Sequence))result.FieldResults.Add(Header(field,pair,crosses));
    var leftItems=pair.Left?.LineItems.OrderBy(x=>x.Sequence).ToList()??[];var rightItems=pair.Right?.LineItems.OrderBy(x=>x.Sequence).ToList()??[];result.LineItemsLeft=leftItems.Count;result.LineItemsRight=rightItems.Count;
    if(!pair.Ambiguous&&pair.Left is not null&&pair.Right is not null){foreach(var match in matcher.Match(leftItems,rightItems)){result.LineItemMatches.Add(match);if(match.Status==LineItemMatchStatus.MATCHED){var l=leftItems.Single(x=>x.Id==match.LeftLineItemId);var r=rightItems.Single(x=>x.Id==match.RightLineItemId);foreach(var field in profile.Fields.Where(x=>x.LineItemScope==LineItemScope.LINE_ITEM).OrderBy(x=>x.Sequence))result.FieldResults.Add(Line(field,l,r));}}}
    result.LineItemsMatched=result.LineItemMatches.Count(x=>x.Status==LineItemMatchStatus.MATCHED);result.LineItemsUnmatched=result.LineItemMatches.Count(x=>x.Status is LineItemMatchStatus.UNMATCHED_LEFT or LineItemMatchStatus.UNMATCHED_RIGHT);
    result.ComparableFieldCount=result.FieldResults.Count;result.MatchCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.MATCH);result.MismatchCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.MISMATCH);result.InsufficientEvidenceCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.INSUFFICIENT_EVIDENCE);result.ManualReviewCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.MANUAL_REVIEW);result.NotApplicableCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.NOT_APPLICABLE);
    var requiredFields=profile.Fields.Where(x=>x.RequiredForCoverage).Select(x=>x.Id).ToHashSet();var expected=result.FieldResults.Count(x=>requiredFields.Contains(x.ProfileFieldId));var evaluated=result.FieldResults.Count(x=>requiredFields.Contains(x.ProfileFieldId)&&x.Outcome is CrossValidationOutcome.MATCH or CrossValidationOutcome.MISMATCH);result.CoveragePercent=expected==0?null:decimal.Round(evaluated*100m/expected,4);
    var ambiguous=pair.Ambiguous||result.LineItemMatches.Any(x=>x.Status==LineItemMatchStatus.AMBIGUOUS);var unmatched=result.LineItemMatches.Any(x=>x.Status is LineItemMatchStatus.UNMATCHED_LEFT or LineItemMatchStatus.UNMATCHED_RIGHT);result.Outcome=result.MismatchCount>0||unmatched?ReconciliationOutcome.WITH_DIFFERENCES:ambiguous||result.ManualReviewCount>0?ReconciliationOutcome.MANUAL_REVIEW:result.InsufficientEvidenceCount>0?ReconciliationOutcome.INSUFFICIENT_EVIDENCE:result.ComparableFieldCount==0?ReconciliationOutcome.NOT_APPLICABLE:ReconciliationOutcome.MATCH;
    result.Explanation=pair.Ambiguous?pair.Explanation:result.Outcome switch{ReconciliationOutcome.MATCH=>"Todos los campos estructurados comparables y partidas vinculadas coinciden.",ReconciliationOutcome.WITH_DIFFERENCES=>"Se detectaron diferencias técnicas o partidas sin correspondencia; no equivale a incumplimiento legal.",ReconciliationOutcome.INSUFFICIENT_EVIDENCE=>"No existe evidencia estructurada suficiente para completar la reconciliación.",ReconciliationOutcome.MANUAL_REVIEW=>"La vinculación documental o de partidas es ambigua y requiere revisión humana.",_=>"No existen campos aplicables para reconciliar."};
    result.SnapshotJson=JsonSerializer.Serialize(new{profile=new{profile.Code,profile.Version},leftDocument=pair.Left is null?null:new{pair.Left.Id,pair.Left.OriginalFileName},rightDocument=pair.Right is null?null:new{pair.Right.Id,pair.Right.OriginalFileName},result.Outcome,result.CoveragePercent,fields=result.FieldResults.Select(x=>new{x.Section,x.LeftFieldCode,x.RightFieldCode,x.LeftRawValue,x.RightRawValue,x.LeftNormalizedValue,x.RightNormalizedValue,x.LeftExtractionMethod,x.RightExtractionMethod,x.Outcome,x.NumericDifference,x.PercentDifference,x.Tolerance,x.RuleCode,x.EvidenceSource,x.Explanation}),lineItems=result.LineItemMatches.Select(x=>new{x.Status,x.MatchMethod,x.MatchKey,x.LeftItemSnapshot,x.RightItemSnapshot,x.Explanation}),evaluatedAt=result.EvaluatedAt});return result;
  }

  private static DocumentReconciliationFieldResult Header(DocumentReconciliationProfileField field,Pair pair,List<CrossValidationResult> crosses){
    var reused=field.CrossValidationRuleId.HasValue?crosses.FirstOrDefault(x=>x.CrossValidationRuleId==field.CrossValidationRuleId&&x.SourceDocumentId==pair.Left?.Id&&x.TargetDocumentId==pair.Right?.Id):null;if(reused is not null)return new(){ProfileFieldId=field.Id,CrossValidationResultId=reused.Id,Section=field.Section,LeftFieldCode=field.LeftFieldCode,RightFieldCode=field.RightFieldCode,LeftRawValue=reused.SourceRawValue,RightRawValue=reused.TargetRawValue,LeftNormalizedValue=reused.SourceNormalizedValue,RightNormalizedValue=reused.TargetNormalizedValue,LeftExtractionMethod=reused.SourceField?.ExtractionMethod,RightExtractionMethod=reused.TargetField?.ExtractionMethod??(reused.TargetFieldId is null&&reused.TargetRawValue is not null?ExtractionMethod.EXISTING_METADATA:null),Outcome=reused.Outcome,NumericDifference=reused.NumericDifference,PercentDifference=reused.PercentDifference,Tolerance=Tolerance(field),RuleCode=reused.RuleCode,EvidenceSource=Evidence(reused.SourceField?.ExtractionMethod,reused.TargetField?.ExtractionMethod),Explanation=$"Resultado CROSS {reused.RuleCode} reutilizado. {reused.Explanation}"};
    var left=Field(pair.Left,field.LeftFieldCode);var right=Field(pair.Right,field.RightFieldCode);return Compare(field,left,right,null,null);
  }
  private static DocumentReconciliationFieldResult Line(DocumentReconciliationProfileField field,DocumentLineItem left,DocumentLineItem right){var l=LineValue(left,field.LeftFieldCode);var r=LineValue(right,field.RightFieldCode);return Compare(field,l,r,left.Id,right.Id);}
  private static DocumentReconciliationFieldResult Compare(DocumentReconciliationProfileField field,ValueSnapshot left,ValueSnapshot right,Guid? leftItem,Guid? rightItem){
    var row=new DocumentReconciliationFieldResult{ProfileFieldId=field.Id,LeftLineItemId=leftItem,RightLineItemId=rightItem,Section=field.Section,LeftFieldCode=field.LeftFieldCode,RightFieldCode=field.RightFieldCode,LeftRawValue=left.Raw,RightRawValue=right.Raw,LeftNormalizedValue=left.Normalized,RightNormalizedValue=right.Normalized,LeftExtractionMethod=left.Method,RightExtractionMethod=right.Method,Tolerance=Tolerance(field),RuleCode=field.CrossValidationRule?.Code,EvidenceSource=Evidence(left.Method,right.Method)};
    if(string.IsNullOrWhiteSpace(left.Normalized)||string.IsNullOrWhiteSpace(right.Normalized)){row.Outcome=CrossValidationOutcome.INSUFFICIENT_EVIDENCE;row.Explanation="Falta evidencia estructurada en al menos uno de los documentos; la ausencia no se considera diferencia.";return row;}
    if(field.ComparisonType is CrossComparisonType.EXACT_NUMERIC or CrossComparisonType.NUMERIC_TOLERANCE or CrossComparisonType.PERCENT_TOLERANCE or CrossComparisonType.CURRENCY_AMOUNT){if(!decimal.TryParse(left.Normalized,NumberStyles.Number,CultureInfo.InvariantCulture,out var lv)||!decimal.TryParse(right.Normalized,NumberStyles.Number,CultureInfo.InvariantCulture,out var rv)){row.Outcome=CrossValidationOutcome.MANUAL_REVIEW;row.Explanation="Los valores no pudieron interpretarse inequívocamente como números.";return row;}row.NumericDifference=Math.Abs(lv-rv);row.PercentDifference=rv==0?(lv==0?0:null):Math.Abs((lv-rv)/rv*100m);var ok=field.ComparisonType switch{CrossComparisonType.EXACT_NUMERIC or CrossComparisonType.CURRENCY_AMOUNT=>row.NumericDifference==0,CrossComparisonType.NUMERIC_TOLERANCE=>row.NumericDifference<=(field.ToleranceValue??0),CrossComparisonType.PERCENT_TOLERANCE=>row.PercentDifference.HasValue&&row.PercentDifference<=(field.ToleranceValue??0),_=>false};row.Outcome=ok?CrossValidationOutcome.MATCH:CrossValidationOutcome.MISMATCH;row.Explanation=ok?"Los valores numéricos coinciden dentro de la tolerancia.":$"Diferencia documental: {row.NumericDifference.Value.ToString(CultureInfo.InvariantCulture)}.";return row;}
    var match=field.ComparisonType==CrossComparisonType.EXACT_TEXT?string.Equals(left.Raw,right.Raw,StringComparison.Ordinal):string.Equals(left.Normalized,right.Normalized,StringComparison.OrdinalIgnoreCase);row.Outcome=match?CrossValidationOutcome.MATCH:CrossValidationOutcome.MISMATCH;row.Explanation=match?"Los valores normalizados coinciden.":"Los valores normalizados son distintos; este resultado es técnico, no legal.";return row;
  }

  private static List<OperationDocument> OfType(List<OperationDocument> docs,string code){var aliases=Aliases.GetValueOrDefault(code)??[code];return docs.Where(x=>aliases.Contains(x.DocumentType.Code,StringComparer.OrdinalIgnoreCase)).OrderBy(x=>x.UploadedAt).ThenBy(x=>x.Id).ToList();}
  private static List<Pair> PairDocuments(List<OperationDocument> left,List<OperationDocument> right){if(left.Count==0)return right.Select(x=>new Pair(null,x,false,"Documento izquierdo no disponible.")).ToList();if(right.Count==0)return left.Select(x=>new Pair(x,null,false,"Documento derecho no disponible.")).ToList();if(left.Count==1&&right.Count==1)return[new(left[0],right[0],false,"Pareja documental única.")];var result=new List<Pair>();var used=new HashSet<Guid>();foreach(var l in left){var keys=Keys(l);var candidates=right.Where(r=>!used.Contains(r.Id)&&keys.Overlaps(Keys(r))).ToList();if(candidates.Count==1){used.Add(candidates[0].Id);result.Add(new(l,candidates[0],false,"Pareja resuelta por referencia documental exacta."));}else if(candidates.Count>1)result.Add(new(l,null,true,"Existen múltiples documentos candidatos con la misma referencia."));else result.Add(new(l,null,true,"No fue posible determinar una pareja documental inequívoca."));}foreach(var r in right.Where(x=>!used.Contains(x.Id)&&result.All(p=>p.Right?.Id!=x.Id)))result.Add(new(null,r,true,"Documento derecho sin pareja inequívoca."));return result;}
  private static HashSet<string> Keys(OperationDocument doc){var values=doc.References.Select(x=>x.Value).Concat(doc.Fields.Where(x=>x.FieldCode is DocumentFieldCodes.InvoiceNumber or DocumentFieldCodes.CoveNumber or DocumentFieldCodes.DocumentNumber).Select(x=>x.NormalizedValue??x.RawValue)).Append(doc.DocumentNumber);return values.Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>Regex.Replace(x!.Trim().ToUpperInvariant(),@"[^A-Z0-9]","")).Where(x=>x.Length>0).ToHashSet(StringComparer.OrdinalIgnoreCase);}
  private static ValueSnapshot Field(OperationDocument? doc,string code){var field=doc?.Fields.Where(x=>x.FieldCode==code).OrderByDescending(x=>Priority(x.ExtractionMethod)).ThenByDescending(x=>x.IsManuallyConfirmed).ThenByDescending(x=>x.Confidence).FirstOrDefault();return new(field?.Id,field?.RawValue,field?.NormalizedValue,field?.ExtractionMethod);}
  private static int Priority(ExtractionMethod method)=>method switch{ExtractionMethod.MANUAL=>5,ExtractionMethod.XML=>4,ExtractionMethod.PDF_TEXT=>3,ExtractionMethod.FILENAME=>2,ExtractionMethod.EXISTING_METADATA=>1,_=>0};
  private static ValueSnapshot LineValue(DocumentLineItem item,string code){object? value=code switch{DocumentFieldCodes.DocumentNumber=>item.ItemNumber,DocumentFieldCodes.Description=>item.Description,DocumentFieldCodes.Quantity=>item.Quantity,DocumentFieldCodes.Unit=>item.Unit,DocumentFieldCodes.UnitPrice=>item.UnitValue,DocumentFieldCodes.TotalAmount or DocumentFieldCodes.CommercialValue=>item.TotalValue,DocumentFieldCodes.Currency=>item.Currency,DocumentFieldCodes.TariffFraction=>item.TariffFraction,DocumentFieldCodes.Nico=>item.Nico,DocumentFieldCodes.GrossWeight=>item.GrossWeight,DocumentFieldCodes.NetWeight=>item.NetWeight,DocumentFieldCodes.OriginCountry=>item.CountryOfOrigin,"PART_NUMBER"=>item.PartNumber??item.Sku,_=>null};var raw=value is IFormattable f?f.ToString(null,CultureInfo.InvariantCulture):value?.ToString();var normalized=code==DocumentFieldCodes.Description?Regex.Replace(raw?.Trim().ToUpperInvariant()??"",@"[\p{P}\s]+"," ").Trim():code==DocumentFieldCodes.Unit?raw?.Trim().ToUpperInvariant() switch{"PIEZA" or "PIEZAS" or "PZ" or "PZS" or "PCS"=>"PZA","KGS"=>"KG","LBS"=>"LB",var v=>v}:raw?.Trim().ToUpperInvariant();return new(null,raw,string.IsNullOrWhiteSpace(normalized)?null:normalized,item.ExtractionMethod);}
  private static string Evidence(ExtractionMethod? left,ExtractionMethod? right)=>$"LEFT:{left?.ToString()??"MISSING"}; RIGHT:{right?.ToString()??"MISSING"}";
  private static string Tolerance(DocumentReconciliationProfileField field)=>field.ToleranceType is null?"EXACT":$"{field.ToleranceType}:{field.ToleranceValue?.ToString(CultureInfo.InvariantCulture)??"0"}";
  private async Task<Guid?> ValidUser(Guid id,CancellationToken ct)=>id!=Guid.Empty&&await db.Users.AnyAsync(x=>x.Id==id,ct)?id:null;
}
